# FILE: Chart.yaml
apiVersion: v2
name: postgres-nonprod
description: A Helm chart for deploying a non-production Postgres database
type: application
version: 0.1.0
appVersion: "16.2"
---
# FILE: values.yaml
# Default values for postgres-nonprod.
# This is a YAML-formatted file.
# Declare variables to be passed into your templates.

replicaCount: 1

image:
  repository: postgres
  tag: "16.2"
  pullPolicy: IfNotPresent

nameOverride: ""
fullnameOverride: ""

service:
  type: ClusterIP
  port: 5432

persistence:
  enabled: true
  size: 10Gi
  storageClass: ""
  accessModes:
    - ReadWriteOnce

resources:
  limits:
    cpu: 500m
    memory: 512Mi
  requests:
    cpu: 250m
    memory: 256Mi

nodeSelector: {}

tolerations: []

affinity: {}

# Database configuration
database:
  name: myapp
  user: myapp
  # Password will be auto-generated if not provided
  password: ""
  # Existing secret name (if password is managed externally)
  existingSecret: ""

# Init job configuration
initJob:
  enabled: true
  backoffLimit: 5
  activeDeadlineSeconds: 300

# Security context
securityContext:
  fsGroup: 999
  runAsUser: 999
  runAsNonRoot: true

# Pod security context
podSecurityContext:
  fsGroup: 999
  runAsUser: 999
  runAsNonRoot: true

# Liveness and readiness probes
livenessProbe:
  initialDelaySeconds: 30
  periodSeconds: 10
  timeoutSeconds: 5
  failureThreshold: 6

readinessProbe:
  initialDelaySeconds: 5
  periodSeconds: 10
  timeoutSeconds: 5
  failureThreshold: 3
---
# FILE: templates/_helpers.tpl
{{- define "postgres-nonprod.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "postgres-nonprod.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{- define "postgres-nonprod.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "postgres-nonprod.labels" -}}
helm.sh/chart: {{ include "postgres-nonprod.chart" . }}
{{ include "postgres-nonprod.selectorLabels" . }}
{{- if .Chart.AppVersion }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
{{- end }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end }}

{{- define "postgres-nonprod.selectorLabels" -}}
app.kubernetes.io/name: {{ include "postgres-nonprod.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end }}

{{- define "postgres-nonprod.serviceAccountName" -}}
{{- if .Values.serviceAccount.create }}
{{- default (include "postgres-nonprod.fullname" .) .Values.serviceAccount.name }}
{{- else }}
{{- default "default" .Values.serviceAccount.name }}
{{- end }}
{{- end }}

{{- define "postgres-nonprod.databaseUrl" -}}
postgresql://{{ .Values.database.user }}:{{ .Values.database.password }}@{{ include "postgres-nonprod.fullname" . }}:{{ .Values.service.port }}/{{ .Values.database.name }}
{{- end }}
---
# FILE: templates/secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}-credentials
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
type: Opaque
data:
  {{- if .Values.database.existingSecret }}
  postgres-password: {{ (lookup "v1" "Secret" .Release.Namespace .Values.database.existingSecret).data.postgres-password | default "" }}
  password: {{ (lookup "v1" "Secret" .Release.Namespace .Values.database.existingSecret).data.password | default "" }}
  {{- else }}
  postgres-password: {{ .Values.database.password | default (randAlphaNum 32) | b64enc | quote }}
  password: {{ .Values.database.password | default (randAlphaNum 32) | b64enc | quote }}
  {{- end }}
  database-name: {{ .Values.database.name | b64enc | quote }}
  database-user: {{ .Values.database.user | b64enc | quote }}
---
# FILE: templates/service-headless.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}-headless
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
spec:
  clusterIP: None
  ports:
    - port: {{ .Values.service.port }}
      targetPort: postgres
      protocol: TCP
      name: postgres
  selector:
    {{- include "postgres-nonprod.selectorLabels" . | nindent 4 }}
---
# FILE: templates/service.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: postgres
      protocol: TCP
      name: postgres
  selector:
    {{- include "postgres-nonprod.selectorLabels" . | nindent 4 }}
---
# FILE: templates/pvc.yaml
{{- if .Values.persistence.enabled }}
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}-data
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
spec:
  accessModes:
    {{- range .Values.persistence.accessModes }}
    - {{ . | quote }}
    {{- end }}
  resources:
    requests:
      storage: {{ .Values.persistence.size | quote }}
  {{- if .Values.persistence.storageClass }}
  storageClassName: {{ .Values.persistence.storageClass | quote }}
  {{- end }}
{{- end }}
